    return a

def get_triples_for_leg_simplified(h):
    triples = []
    if h % 2 != 0: return []
    target = h // 2
    # s is a scaling factor for primitive triples
    for s in range(1, target + 1):
        if target % s == 0:
            mn = target // s
            for n in range(1, int(math.sqrt(mn)) + 1):
                if mn % n == 0:
                    m = mn // n
                    if m > n and gcd(m, n) == 1 and (m - n) % 2 == 1:
                        leg = s * (m * m - n * n)
                        hyp = s * (m * m + n * n)
                        triples.append((leg, hyp))
    return sorted(list(set(triples)))

def generator(rng):
